fn process_voxel(x: u32, y: u32) {
    let idx = get_idx(x, y);
    let voxel = grid_in[idx];
    let mat = get_material(voxel);
    if (mat == MAT_AIR) { grid_out[idx] = voxel; return; }

    let block_phase = ((x >> 1u) + (y >> 1u)) & 3u;
    let self_thermal = get_thermal(voxel);
