fn classify_chunks(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let chunk_x = wid.x;
    let chunk_y = wid.y;
    let chunk_id = chunk_y * CHUNKS_X + chunk_x;
    let local_idx = lid.y * 16u + lid.x;

    // Initialize workgroup shared memory
    if (local_idx == 0u) {
        atomicStore(&chunk_has_active, 0u);
    }
    workgroupBarrier();

    // Check if this thread's voxel is active
    let voxel_x = chunk_x * CHUNK_SIZE + lid.x;
    let voxel_y = chunk_y * CHUNK_SIZE + lid.y;

    var found_active = false;

    if (voxel_x < GRID_WIDTH && voxel_y < GRID_HEIGHT) {
        let voxel = grid_in[get_idx(voxel_x, voxel_y)];
        if (get_material(voxel) != MAT_AIR) {
            found_active = true;
        }
    }

    // Vectorized border checks for edge threads
    if (!found_active) {
        // Left border check
        if (lid.x == 0u && voxel_x > 0u && voxel_y < GRID_HEIGHT) {
            let border_voxel = grid_in[get_idx(voxel_x - 1u, voxel_y)];
            if (get_material(border_voxel) != MAT_AIR) {
                found_active = true;
            }
        }
        // Right border check
        if (lid.x == 15u && voxel_x < GRID_WIDTH - 1u && voxel_y < GRID_HEIGHT) {
            let border_voxel = grid_in[get_idx(voxel_x + 1u, voxel_y)];
            if (get_material(border_voxel) != MAT_AIR) {
                found_active = true;
            }
        }
        // Top border check
        if (lid.y == 0u && voxel_y > 0u && voxel_x < GRID_WIDTH) {
            let border_voxel = grid_in[get_idx(voxel_x, voxel_y - 1u)];
            if (get_material(border_voxel) != MAT_AIR) {
                found_active = true;
            }
        }
        // Bottom border check
        if (lid.y == 15u && voxel_y < GRID_HEIGHT - 1u && voxel_x < GRID_WIDTH) {
            let border_voxel = grid_in[get_idx(voxel_x, voxel_y + 1u)];
            if (get_material(border_voxel) != MAT_AIR) {
                found_active = true;
            }
        }
    }

    // Only update atomic if we found activity
    if (found_active) {
        atomicStore(&chunk_has_active, 1u);
    }

    workgroupBarrier();

    // One thread writes result
    if (local_idx == 0u) {
        let is_active = atomicLoad(&chunk_has_active);
        chunk_activity[chunk_id] = is_active;
        if (is_active == 1u) {
            let active_idx = atomicAdd(&active_count, 1u);
            active_chunks[active_idx] = chunk_id;
        }
    }
}

fn dispatch_active(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let active_idx = wid.x + wid.y * 256u; // Support up to 65536 active chunks
    let num_active = atomicLoad(&active_count);

    if (active_idx >= num_active) {
        return; // This workgroup has no chunk to process
    }

    let chunk_id = active_chunks[active_idx];
    let chunk_x = chunk_id % CHUNKS_X;
    let chunk_y = chunk_id / CHUNKS_X;

    let voxel_x = chunk_x * CHUNK_SIZE + lid.x;
    let voxel_y = chunk_y * CHUNK_SIZE + lid.y;

    if (voxel_x < GRID_WIDTH && voxel_y < GRID_HEIGHT) {
        process_voxel(voxel_x, voxel_y);
    }
}

