// Variant: Hierarchical chunk classification with reduced atomic ops and better memory coalescing

@group(0) @binding(0) var<storage, read> grid_in: array<u32>;
@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;
@group(0) @binding(2) var<storage, read_write> chunk_activity: array<u32>;
@group(0) @binding(3) var<storage, read_write> active_chunks: array<u32>;
@group(0) @binding(4) var<storage, read_write> active_count: atomic<u32>;

const CHUNK_SIZE: u32 = 16u;
const CHUNKS_X: u32 = 64u;  // GRID_WIDTH / CHUNK_SIZE
const CHUNKS_Y: u32 = 64u;  // GRID_HEIGHT / CHUNK_SIZE
const MAT_AIR: u32 = 0u;
const GRID_WIDTH: u32 = 1024u;
const GRID_HEIGHT: u32 = 1024u;

var<workgroup> chunk_has_active: atomic<u32>;
var<workgroup> local_activity_bits: array<u32, 16>; // One bit per row

fn get_idx(x: u32, y: u32) -> u32 { 
    return y * GRID_WIDTH + x; 
}

fn get_material(packed: u32) -> u32 { 
    return (packed >> MATERIAL_SHIFT) & MATERIAL_MASK; 
}

fn get_thermal(packed: u32) -> u32 { 
    return (packed >> THERMAL_SHIFT) & THERMAL_MASK; 
}

fn set_thermal(packed: u32, thermal: u32) -> u32 {
    return (packed & ~(THERMAL_MASK << THERMAL_SHIFT)) | ((thermal & THERMAL_MASK) << THERMAL_SHIFT);
}

fn process_voxel(x: u32, y: u32) {
    let idx = get_idx(x, y);
    let voxel = grid_in[idx];
    let mat = get_material(voxel);
    if (mat == MAT_AIR) { 
        grid_out[idx] = voxel; 
        return; 
    }

    let block_phase = ((x >> 1u) + (y >> 1u)) & 3u;
    let self_thermal = get_thermal(voxel);
    var thermal_sum = self_thermal << 4u;
    var weight_sum = 16u;
    var packed_cardinals = vec4<u32>(0u, 0u, 0u, 0u);
    var packed_diagonals = vec4<u32>(0u, 0u, 0u, 0u);
    var valid_mask = 0u;

    if (y > 0u) { 
        let n = grid_in[idx - GRID_WIDTH]; 
        if (get_material(n) != MAT_AIR) { 
            packed_cardinals.x = get_thermal(n); 
            valid_mask |= 1u; 
        } 
    }
    if (x < GRID_WIDTH - 1u) { 
        let n = grid_in[idx + 1u]; 
        if (get_material(n) != MAT_AIR) { 
            packed_cardinals.y = get_thermal(n); 
            valid_mask |= 2u; 
        } 
    }
    if (y < GRID_HEIGHT - 1u) { 
        let n = grid_in[idx + GRID_WIDTH]; 
        if (get_material(n) != MAT_AIR) { 
            packed_cardinals.z = get_thermal(n); 
            valid_mask |= 4u; 
        } 
    }
    if (x > 0u) { 
        let n = grid_in[idx - 1u]; 
        if (get_material(n) != MAT_AIR) { 
            packed_cardinals.w = get_thermal(n); 
            valid_mask |= 8u; 
        } 
    }

    if ((block_phase & 1u) == 0u) {
        if (x < GRID_WIDTH - 1u && y > 0u) { 
            let n = grid_in[idx - GRID_WIDTH + 1u]; 
            if (get_material(n) != MAT_AIR) { 
                packed_diagonals.x = get_thermal(n); 
                valid_mask |= 16u; 
            } 
        }
        if (x > 0u && y < GRID_HEIGHT - 1u) { 
            let n = grid_in[idx + GRID_WIDTH - 1u]; 
            if (get_material(n) != MAT_AIR) { 
                packed_diagonals.z = get_thermal(n); 
                valid_mask |= 32u; 
            } 
        }
    }
    if (block_phase >= 2u) {
        if (x < GRID_WIDTH - 1u && y < GRID_HEIGHT - 1u) { 
            let n = grid_in[idx + GRID_WIDTH + 1u]; 
            if (get_material(n) != MAT_AIR) { 
                packed_diagonals.y = get_thermal(n); 
                valid_mask |= 64u; 
            } 
        }
        if (x > 0u && y > 0u) { 
            let n = grid_in[idx - GRID_WIDTH - 1u]; 
            if (get_material(n) != MAT_AIR) { 
                packed_diagonals.w = get_thermal(n); 
                valid_mask |= 128u; 
            } 
        }
    }

    let cv = vec4<u32>((valid_mask) & 1u, (valid_mask >> 1u) & 1u, (valid_mask >> 2u) & 1u, (valid_mask >> 3u) & 1u);
    let dv = vec4<u32>((valid_mask >> 4u) & 1u, (valid_mask >> 5u) & 1u, (valid_mask >> 6u) & 1u, (valid_mask >> 7u) & 1u);
    thermal_sum += (dot(packed_cardinals, cv) << 1u) + dot(packed_diagonals, dv);
    weight_sum += (dot(cv, vec4<u32>(1u, 1u, 1u, 1u)) << 1u) + dot(dv, vec4<u32>(1u, 1u, 1u, 1u));
    grid_out[idx] = set_thermal(voxel, thermal_sum / weight_sum);
}

fn classify_chunks(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let chunk_x = wid.x;
    let chunk_y = wid.y;
    let chunk_id = chunk_y * CHUNKS_X + chunk_x;
    let local_idx = lid.y * 16u + lid.x;

    // Initialize shared memory
    if (local_idx == 0u) {
