    }

    // Border checks - only threads on edges need to check
    if (lid.x == 0u && voxel_x > 0u && voxel_y < GRID_HEIGHT) {
        if (get_material(grid_in[get_idx(voxel_x - 1u, voxel_y)]) != MAT_AIR) {
