        }
    }
    if (lid.x == 15u && voxel_x < GRID_WIDTH - 1u && voxel_y < GRID_HEIGHT) {
        if (get_material(grid_in[get_idx(voxel_x + 1u, voxel_y)]) != MAT_AIR) {
            atomicStore(&chunk_has_active, 1u);
        }
    }
    if (lid.y == 0u && voxel_y > 0u && voxel_x < GRID_WIDTH) {
        if (get_material(grid_in[get_idx(voxel_x, voxel_y - 1u)]) != MAT_AIR) {
