        let is_active = atomicLoad(&chunk_has_active);
        chunk_activity[chunk_id] = is_active;
        if (is_active == 1u) {
            let active_idx = atomicAdd(&active_count, 1u);
            active_chunks[active_idx] = chunk_id;
        }
    }
}

